CREATE TABLE "TransferenciasAlmacen" (
                                         "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
                                         "ProductoId" integer NOT NULL,
                                         "AlmacenOrigenId" integer NOT NULL,
                                         "AlmacenDestinoId" integer NOT NULL,
                                         "Cantidad" integer NOT NULL,
                                         "CostoUnitario" numeric(18,4) NOT NULL,
                                         "Fecha" timestamp with time zone NOT NULL,
                                         "Observaciones" character varying(500),
                                         CONSTRAINT "PK_TransferenciasAlmacen" PRIMARY KEY ("Id"),
                                         CONSTRAINT "FK_TransferenciasAlmacen_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
                                         CONSTRAINT "FK_TransferenciasAlmacen_Almacenes_AlmacenOrigenId" FOREIGN KEY ("AlmacenOrigenId") REFERENCES "Almacenes" ("Id") ON DELETE RESTRICT,
                                         CONSTRAINT "FK_TransferenciasAlmacen_Almacenes_AlmacenDestinoId" FOREIGN KEY ("AlmacenDestinoId") REFERENCES "Almacenes" ("Id") ON DELETE RESTRICT,
                                         CONSTRAINT "CK_TransferenciasAlmacen_Cantidad" CHECK ("Cantidad" BETWEEN 1 AND 1000000),
                                         CONSTRAINT "CK_TransferenciasAlmacen_Costo" CHECK ("CostoUnitario" > 0),
                                         CONSTRAINT "CK_TransferenciasAlmacen_Almacenes" CHECK ("AlmacenOrigenId" <> "AlmacenDestinoId")
);

CREATE INDEX "IX_TransferenciasAlmacen_ProductoId" ON "TransferenciasAlmacen" ("ProductoId");
CREATE INDEX "IX_TransferenciasAlmacen_AlmacenOrigenId" ON "TransferenciasAlmacen" ("AlmacenOrigenId");
CREATE INDEX "IX_TransferenciasAlmacen_AlmacenDestinoId" ON "TransferenciasAlmacen" ("AlmacenDestinoId");
CREATE INDEX "IX_TransferenciasAlmacen_Fecha" ON "TransferenciasAlmacen" ("Fecha");

ALTER TABLE "MovimientosKardex" ADD COLUMN "TransferenciaId" integer;
ALTER TABLE "MovimientosKardex" ADD CONSTRAINT "FK_MovimientosKardex_TransferenciasAlmacen_TransferenciaId" FOREIGN KEY ("TransferenciaId") REFERENCES "TransferenciasAlmacen" ("Id") ON DELETE RESTRICT;
CREATE INDEX "IX_MovimientosKardex_TransferenciaId" ON "MovimientosKardex" ("TransferenciaId");